import{z as s,x as B,o as i,c as p,q as l,j as n,D as e,d as t,s as o,S as d,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"参数良率与 CD 分布","description":"","frontmatter":{"title":"参数良率与 CD 分布","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/parametric-yield-cd.md","filePath":"litho/parametric-yield-cd.md","lastUpdated":1791063341000}'),A={name:"litho/parametric-yield-cd.md"};function C(D,a,m,h,c,P){const r=B("Mermaid");return i(),p("div",null,[a[2]||(a[2]=l('<h1 id="参数良率与-cd-分布" tabindex="-1">参数良率与 CD 分布 <a class="header-anchor" href="#参数良率与-cd-分布" aria-label="Permalink to &quot;参数良率与 CD 分布&quot;">​</a></h1><div class="epigraph"><p>缺陷为零仍可能参数死：栅长、via 电阻、匹配对的 CD 分布让时序或漏电出格。这笔良率吃的是分布尾巴，不是颗粒计数。</p><footer>—— 对照参数良率与 CD 控制；Levinson 对 CDU 与电学的衔接</footer></div><p><a href="/litho/yield-learning-curve">上一课</a>把缺陷学习画完。缺口是电学分布：均值 CD 在规格内，尾巴上的管芯时序失败。<a href="/litho/cdu-etch-bias">CDU</a> 与 <a href="/litho/edge-placement-error">EPE</a> 已有纳米账；本课钉参数良率。可靠性与潜在图形缺陷，留给<a href="/litho/reliability-patterning-defects">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>参数良率：性能/漏电/匹配对规格。驱动量包括栅 CD、fin 宽度、via 电阻（开口 CD + 填充）、金属电阻（槽 CD）。分布来自镜头、胶、刻蚀负载、CMP、机台差。EPE 尾巴让 via 覆盖变电阻尾巴。缺陷检测全绿时，参数仍可红。</p><p><span class="marginnote">参数良率可以类比考试：缺陷良率问「交没交卷」（器件做没做出来），参数良率问「过没过线」（速度、功耗、匹配达标与否）。栅宽偏几纳米时器件照样活着，但整条关键路径的时序可能已经不及格。</span></p><p>缺口是<strong>把 CDU 地图换成电学失败率</strong>，不是再定义 3σ。SRAM 失配、逻辑关键路径对 CD 敏感函数不同，全局加剂量可能救平均、害匹配。</p><h3 id="规格是电学的-代理是-cd" tabindex="-1">规格是电学的，代理是 CD <a class="header-anchor" href="#规格是电学的-代理是-cd" aria-label="Permalink to &quot;规格是电学的，代理是 CD&quot;">​</a></h3><p>把 CD 规格当神圣，可能过严（浪费窗口）或过宽（参数死）。应以电学灵敏度标定 CD 规格，并分层：均值进 APC，方差进能力（匹配、负载、随机 LER）。LER 器件课已有；参数良率把阵列失配算进去。</p><p><span class="marginnote">刻蚀密度斜率是参数良率的布局项：同一芯片上 SRAM 与逻辑均值差，不是随机 σ。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>映射：CD 分布 × 灵敏度 → 参数失败率。数据：电学 WAT/探针分 bin、对位到场坐标。动作：减方差（匹配、负载 dummy、OPC 分区），而不是只钉均值。与随机：via 打开是缺陷良率；via 偏小是参数——分类要靠复检+电学。</p><p>灵敏度来自器件或电路仿真，但要用硅上分 bin 校准，避免模型过敏感。Levinson 把 CDU 接到电学；本课要求这根线可画在场坐标上，从而认出边缘场和混机双峰。</p>',13)),(i(),n(d,null,{default:e(()=>[o(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20WAT%5B%22%E7%94%B5%E5%AD%A6%20WAT%20%2F%20%E5%88%86%20bin%22%5D%20--%3E%20MAP%5B%22%E6%8C%89%E5%9C%BA%E5%9D%90%E6%A0%87%E8%B4%B4%E5%9B%9E%E6%99%B6%E5%9C%86%E5%9B%BE%22%5D%0A%20%20MAP%20--%3E%20SHAPE%7B%22%E5%88%86%E5%B8%83%E5%BD%A2%E7%8A%B6%3F%22%7D%0A%20%20SHAPE%20--%3E%7C%22%E5%8D%95%E5%B3%B0%E4%BD%86%E5%AE%BD%22%7C%20VAR%5B%22%E9%9A%8F%E6%9C%BA%E6%96%B9%E5%B7%AE%3A%20%E5%8C%B9%E9%85%8D%E5%AF%B9%20%2F%20dummy%20%2F%20OPC%20%E5%88%86%E5%8C%BA%22%5D%0A%20%20SHAPE%20--%3E%7C%22%E5%8F%8C%E5%B3%B0%22%7C%20MIX%5B%22%E6%B7%B7%E6%9C%BA%E6%88%96%E8%BE%B9%E7%BC%98%E5%9C%BA%3A%20dedication%20%2F%20%E6%9C%BA%E5%8F%B0%E5%8C%B9%E9%85%8D%22%5D%0A%20%20VAR%20--%3E%20FIX%5B%22%E6%8A%AC%E5%8F%82%E6%95%B0%E8%89%AF%E7%8E%87%22%5D%0A%20%20MIX%20--%3E%20FIX%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"失败率 \\(\\approx P(|\\mathrm{CD}-\\mathrm{target}| \\gt \\mathrm{spec})\\) 经电学函数扭曲。非高斯尾巴（边缘场、双机混流）主导。机台对套刻把 via 电阻分布拉宽。APC 切均值不切混流双峰——dedication 或匹配才切双峰。",-1)),(i(),n(d,null,{default:e(()=>[o(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20CDU%5B%22CD%20%2F%20EPE%20%E5%88%86%E5%B8%83%22%5D%20--%3E%20ELEC%5B%22%E7%94%B5%E5%AD%A6%E7%81%B5%E6%95%8F%E5%BA%A6%22%5D%0A%20%20ELEC%20--%3E%20PY%5B%22%E5%8F%82%E6%95%B0%E5%A4%B1%E8%B4%A5%E7%8E%87%22%5D%0A%20%20MIX%5B%22%E6%B7%B7%E6%9C%BA%E5%8F%8C%E5%B3%B0%20%2F%20%E8%B4%9F%E8%BD%BD%E5%B7%AE%22%5D%20--%3E%20TAIL%5B%22%E5%B0%BE%E5%B7%B4%22%5D%0A%20%20TAIL%20--%3E%20PY%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p>混机双峰和负载均值差都在尾巴里，不是随机 σ。减方差比只钉均值更能抬参数良率。</p><p><span class="marginnote">感受尾巴的威力：单机台 CD 偏差若 σ=2 nm，偏出 4 nm 的概率约 5%；两台均值差 3 nm 的机器混流后，最差一侧的远尾概率成倍抬高。参数失败率正比于尾巴面积，所以先拆混流、再谈随机方差。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写器件紧凑模型全文。不把未公开的 \\(V_t\\) 数字当文献。功能缺陷与参数要分 bin。</p><p><span class="marginnote">初学者容易把「检测全绿」当成参数安全的证据：光学检测看得见颗粒与桥连这类「有没有」，看不见 via 开口偏小 2 nm 这种「好不好」。via 完全没打开是缺陷账，开了但偏小是参数账——分家靠复检加电学，不靠一张缺陷图。</span></p><p>后课默认：参数良率看分布尾巴与布局均值差。下一课有些「参数」其实是可靠性潜伏的图形缺陷。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>参数良率吃 CD/EPE 分布与电学灵敏度，检测全绿仍可死。</li><li>减方差（匹配、负载、dedication）比只钉均值更关键。</li><li>布局均值差不是随机 σ。</li><li>via 打开是缺陷账，via 偏小是参数账，分类靠复检加电学。</li><li>出处：Levinson 对 CDU 与电学；参数良率通称。</li></ul>',8))])}const _=s(A,[["render",C]]);export{u as __pageData,_ as default};
